#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT_LEN 1023
#define OUT_BUF_SIZE 4096

static void do_escape(const char *in)
{
    char out[OUT_BUF_SIZE];
    size_t out_i = 0;
    for (size_t i = 0; in[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)in[i];
        switch (c) {
            case '\\':
                out[out_i++] = '\\';
                out[out_i++] = '\\';
                break;
            case '\n':
                out[out_i++] = '\\';
                out[out_i++] = 'n';
                break;
            case '\t':
                out[out_i++] = '\\';
                out[out_i++] = 't';
                break;
            case '"':
                out[out_i++] = '\\';
                out[out_i++] = '"';
                break;
            default:
                out[out_i++] = c;
                break;
        }
    }
    out[out_i] = '\0';
    puts(out);
}

static void do_unescape(const char *in)
{
    char out[OUT_BUF_SIZE];
    size_t out_i = 0;
    size_t i = 0;
    size_t len = strlen(in);
    while (i < len) {
        if (in[i] == '\\') {
            if (i + 1 >= len) {
                puts("INVALID");
                return;
            }
            char nxt = in[i + 1];
            switch (nxt) {
                case '\\':
                    out[out_i++] = '\\';
                    i += 2;
                    continue;
                case 'n':
                    out[out_i++] = '\n';
                    i += 2;
                    continue;
                case 't':
                    out[out_i++] = '\t';
                    i += 2;
                    continue;
                case '"':
                    out[out_i++] = '"';
                    i += 2;
                    continue;
                default:
                    puts("INVALID");
                    return;
            }
        } else {
            out[out_i++] = in[i];
            ++i;
        }
    }
    out[out_i] = '\0';
    puts(out);
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    if (strlen(input) > MAX_INPUT_LEN) {
        puts("USAGE");
        return 0;
    }
    if (strcmp(mode, "escape") == 0) {
        do_escape(input);
    } else if (strcmp(mode, "unescape") == 0) {
        do_unescape(input);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
